document.addEventListener('DOMContentLoaded', () => {
    const deleteDialog = document.getElementById('deleteDialog');
    const triggerButtons = document.querySelectorAll('.trigger');
    const cancelButton = deleteDialog.querySelector('[data-action="cancel"]');
    const confirmButton = deleteDialog.querySelector('[data-action="confirm"]');

    // Open dialog when trigger is clicked
    triggerButtons.forEach(button => {
        button.addEventListener('click', () => {
            deleteDialog.showModal();
            // Focus the cancel button when dialog opens
            cancelButton.focus();
        });
    });

    // Cancel button closes the dialog
    cancelButton.addEventListener('click', () => {
        deleteDialog.close();
    });

    // Confirm button (delete action)
    confirmButton.addEventListener('click', () => {
        console.log('Image deleted');
        deleteDialog.close();
        // Here you would typically send a delete request to your server
    });

    // Close dialog with Escape key (native dialog behavior)
    // but we can also handle it explicitly if needed
    deleteDialog.addEventListener('cancel', () => {
        deleteDialog.close();
    });
});

